/* dkrt_status result. The caller owns the memory; the layout only grows at the end. */
typedef struct DkrtStatus {
    uint32_t magic;                              /* 'DKRT' */
    uint32_t runtime;                            /* RUNTIME_VERSION, major << 16 | minor << 8 | patch */
    uint32_t device;                             /* the digikit device id */
    uint32_t arena_base;                         /* the module arena */
    uint32_t arena_size;
    uint32_t arena_free;
    uint32_t arena_largest;
    uint32_t modules;                            /* modules loaded */
    uint32_t ticks;                              /* UI-loop passes seen */
    int32_t last_result;                         /* result of the last load */
    uint32_t loads;
    uint32_t slot_calls;
    uint32_t state;                              /* STATE_IDLE or STATE_LOADING (a module's DSP code is being sent) */
    uint32_t dsp_size;                           /* bytes of the DSP area (0: the image has none) */
    uint32_t dsp_free;                           /* bytes of it free */
    uint32_t dsp_largest;                        /* the largest free range */
} DkrtStatus;

/* One entry of dkrt_capacity (the CAPACITY command's entries; kind is a CAPK_* number). largest is 0 where a largest piece has no meaning. The layout only grows at the end. */
typedef struct DkrtCap {
    uint32_t kind;                               /* CAPK_* */
    uint32_t limit;
    uint32_t used;
    uint32_t largest;
} DkrtCap;

/* dkrt_health result (finding 41). The caller owns the memory; the layout only grows at the end. A figure is valid when its flag is set; the others are 0. Loads are in tenths of a percent (0 to 1000). */
typedef struct DkrtHealth {
    uint32_t magic;                              /* HEALTH_MAGIC */
    uint32_t version;                            /* 3 */
    uint32_t flags;                              /* HEALTH_* */
    uint32_t blocks;                             /* DSP blocks seen since boot (1500 per second) */
    uint32_t windows;                            /* windows (one second each) closed */
    uint32_t cpu_x10;                            /* CPU load of the last window, tenths of a percent, relative to the quietest window since boot (HEALTH_CPU) */
    uint32_t idle_win;                           /* the idle-loop iterations in the last window */
    uint32_t idle_ref;                           /* the best window so far (100 % idle) */
    uint32_t dsp_avg;                            /* DSP block handler, cycles per block, average of the last window (the DSP's own EMUCLK difference) */
    uint32_t dsp_max;                            /* maximum of the last window */
    uint32_t dsp_period;                         /* the cycles a block has (DSP_BLOCK_CYCLES) */
    uint32_t dsp_avg_x10;                        /* dsp_avg as tenths of a percent of dsp_period, an assumed 1 GHz block (finding 100) (HEALTH_DSP) */
    uint32_t dsp_max_x10;                        /* dsp_max as tenths of a percent of dsp_period */
    uint32_t heap_total;                         /* the firmware heap (HEALTH_HEAP): bytes in all */
    uint32_t heap_free;
    uint32_t heap_largest;                       /* the largest free block */
    uint32_t heap_allocs;                        /* live allocations */
    uint32_t heap_free_blocks;                   /* free blocks walked */
    uint32_t arena_total;                        /* the runtime's module arena: bytes in all */
    uint32_t arena_free;
    uint32_t arena_largest;
    uint32_t dsp_area_total;                     /* the DSP area (0: the image has none): bytes in all */
    uint32_t dsp_area_free;
    uint32_t dsp_area_largest;
    uint32_t store_total;                        /* the module store (HEALTH_STORE), in KiB: the store may use in all (header, tables and files) */
    uint32_t store_used;                         /* KiB the current header says are used */
    uint32_t store_free;                         /* KiB a new file may still take in all (the room for the table's next entry kept back; not one contiguous piece) */
} DkrtHealth;

/* A store file for the DIGIKIT menu (dkrt_store_list): its path (at most 63 bytes, NUL-terminated), the first sector (relative to the store) and the size in bytes. */
typedef struct DkrtStoreEntry {
    uint8_t path[64];
    uint32_t first;
    uint32_t size;
} DkrtStoreEntry;

/* A store file as dkrt_store_stat found it, for an adapter that streams it (dkrt_store_read): the first sector (relative to the store), the size in bytes and the sha256 of the table entry. The file's sectors are contiguous: sector n of the file is store sector first + n. */
typedef struct DkrtStoreFile {
    uint32_t first;
    uint32_t size;
    uint8_t sha[32];
} DkrtStoreFile;

/* dkrt_module result: one loaded module. */
typedef struct DkrtModule {
    uint8_t name[32];
    uint32_t version;
    uint32_t base;
    uint32_t size;
    uint32_t slots;                              /* bit n = slot n bound */
    uint8_t path[64];                            /* store path the module was loaded from (NUL-terminated, at most 63 bytes kept), for example modules/dyn-demo.dkm */
    uint32_t state;                              /* MOD_LOADED or MOD_LOADING */
    uint32_t dsp_size;                           /* bytes of the module's range in the DSP area (0: none) */
    uint32_t menu;                               /* address of the module's dkm_menu(dk_ui_menu *, void *) settings entry point (0: none) */
} DkrtModule;

/* dkrt_fx result: one effect with a page (FX routing, finding 62 to 65). Routes are bit masks: 1 master, 2 send. */
typedef struct DkrtFx {
    uint32_t row;                                /* the effect's row in the chain */
    uint32_t allowed;                            /* the routes the effect's record allows (routes of the manifest) */
    uint32_t dflt;                               /* its default route (route) */
    uint32_t running;                            /* the route it runs on in this boot */
    uint32_t saved;                              /* the route the settings give it now (the stored one when allowed, else the default): differs from running after a change before the restart */
    uint8_t tab[8];                              /* the tab label of its page (NUL-terminated, up to 3 characters) */
    uint8_t id[32];                              /* the id of its module (NUL-terminated): the settings key is fx/route/<id> */
} DkrtFx;

/* The selection (what the next boot loads), the layout the menu passes to dkrt_selection_set and gets from dkrt_selection_get. Paths are store paths (modules/dyn-pluck.dkm), NUL terminated, at most SEL_PATH - 1 characters. */
typedef struct DkrtSelection {
    uint32_t count;                              /* number of paths in use, 0 to SEL_MAX */
    uint32_t flags;                              /* bit 0: start in safe mode once (the boot that honours it clears the bit) */
    uint8_t paths[DKRT_SEL_MAX][DKRT_SEL_PATH];
} DkrtSelection;

/* dkrt_boot_info result: this boot. */
typedef struct DkrtBootInfo {
    uint32_t magic;                              /* 'DKBT' */
    uint32_t version;
    uint32_t safe;                               /* 1 when this boot loaded nothing because of safe mode */
    uint32_t reason;                             /* SAFE_* why */
    uint32_t counter;                            /* the boot counter as the record held it at the start of this boot (before the runtime raised it) */
    uint32_t seq;                                /* sequence number of the record in use (0: no valid record) */
    uint32_t copy;                               /* which copy held it (0 = A, 1 = B) */
    uint32_t count;                              /* modules selected */
    uint32_t loaded;                             /* how many of them loaded without an error */
    uint32_t ui_reached;                         /* 1 once the UI loop has run (the boot counter is back to 0) */
    int32_t results[DKRT_SEL_MAX];               /* OK, a negative code, or LOADING (the CF part is live, the DSP part is still going) per selected module, in selection order */
    uint32_t dsp_wait;                           /* reserved (0): the boot does not wait for DSP code */
    uint32_t stable;                             /* 1 once the boot counter is back to 0: after STABLE_BLOCKS DSP blocks of UI loop in a normal boot, at the first UI-loop pass in a safe boot */
} DkrtBootInfo;

/* dkrt_diag result (finding 46): what the debug log and the card check found. The caller owns the memory; the layout only grows at the end. */
typedef struct DkrtDiag {
    uint32_t magic;                              /* DIAG_MAGIC */
    uint32_t version;
    uint32_t card_state;                         /* CARD_* */
    uint32_t card_first_nonblank;                /* the first sector (relative to the store) that was not blank (0xffffffff: none) */
    uint32_t card_hash;                          /* a crc32 of it */
    uint32_t card_refused;                       /* card writes refused (range or read-only) */
    uint32_t card_read_errors;                   /* reads that failed in the check */
    uint32_t debug_on;                           /* 1 while a debug module (the log sink) is loaded */
    uint32_t log_oldest;                         /* 0 (the log ring is the debug module's; its LOG command has the range) */
    uint32_t log_newest;                         /* 0 */
    uint32_t dsp_diag_ok;                        /* 1 when dl_diag is in the image and answered */
    uint32_t dsp_stopped;                        /* 1 when the heartbeat watch decided the DSP stopped */
    uint32_t dsp_heartbeat;                      /* the last heartbeat word */
    uint32_t crash_found;                        /* a crash record from the boot before was found at this boot: 1 */
    uint32_t crash_pc;                           /* its program counter */
    uint32_t crash_vec;                          /* its vector */
    uint32_t ram_kept;                           /* 1 when the keep-probe word of the boot before was still in RAM at this boot (RAM survived the reset that led here) */
    uint32_t dsp_crumb;                          /* the DSP's last breadcrumb when the watch decided it stopped (0 before): stage | voice << 8 | machine type << 16 (finding 48) */
    uint32_t fault_rows;                         /* rows of fault_text that are filled: the last fault kept in the settings key dk/fault (0: none) */
    uint8_t fault_text[DKRT_FAULT_ROWS][24];     /* the ABOUT rows of that fault, upper case, at most 18 characters (the ABOUT page width on DT2) and a NUL */
} DkrtDiag;

/* dkrt_module_header result: what the DIGIKIT menu shows of a .dkm header. The layout only grows at the end. */
typedef struct DkrtModuleHeader {
    uint32_t version;                            /* the module's version, major << 16 | minor << 8 | patch */
} DkrtModuleHeader;

/* One .dkm file of the store as dkrt_scan found it: where it is, what its header says and the needs inferred from its contents (dkneeds). The need_* fields are valid when SCAN_NEEDS is set. */
typedef struct DkrtScan {
    uint8_t path[64];                            /* store path, NUL-terminated, for example modules/dyn-demo.dkm */
    uint32_t first;                              /* first sector (relative to the store) */
    uint32_t size;                               /* bytes */
    uint32_t flags;                              /* SCAN_* */
    uint32_t need_file_size;                     /* the file's size: it must fit the staging buffer */
    uint32_t need_arena;                         /* the arena block of image and bss */
    uint32_t need_arena_xfer;                    /* the arena block of the relocated DSP image, held while it is sent (0: no DSP section) */
    uint32_t need_dsp_area;                      /* DSP area bytes: image, bss and voice states (0: no DSP section) */
    uint32_t need_dsp_align;
    uint32_t need_machine_rows;
    uint32_t need_voice_rows;
    uint32_t need_param_rows;
    uint32_t need_page_rows;
    uint32_t need_fx_slots;
} DkrtScan;

/* The fit verdict of one DkrtScan entry. wont is 1 when the module does not fit next to the ticked ones; then short_* is the first short resource (a CAPK_* kind, what the module needs and what is free) and the texts say it. mem is the memory the module takes (arena and DSP area) as text. */
typedef struct DkrtFitRow {
    uint32_t wont;
    uint32_t short_kind;
    uint32_t short_need;
    uint32_t short_free;
    uint8_t reason[DKRT_FIT_REASON];             /* upper case, for a popup: DSP 400K > 254K FREE */
    uint8_t brief[DKRT_FIT_BRIEF];               /* for a list row: DSP 400K>254K */
    uint8_t mem[DKRT_FIT_MEM];                   /* <1K, 259K, 1.2M; empty without SCAN_NEEDS */
} DkrtFitRow;

/* dkrt_fit result: one row per entry and the load line of the ticked set. */
typedef struct DkrtFitOut {
    uint32_t count;                              /* rows written */
    uint8_t line[DKRT_FIT_LINE];                 /* DSP 52% CPU 1%; empty when nothing is ticked */
    DkrtFitRow rows[DKRT_SCAN_MAX];
} DkrtFitOut;

